// Contrato de entrada del endpoint POST /webhook/laia
// Body JSON: { "query": string (1-1000), "session_id": string (3-100, letras, números, - y _) }
const body = ($input.first().json.body) || {};
const errores = [];

const query = typeof body.query === 'string' ? body.query.trim() : '';
if (typeof body.query !== 'string') errores.push({ campo: 'query', problema: 'Es obligatorio y debe ser texto.' });
else if (query.length === 0) errores.push({ campo: 'query', problema: 'No puede estar vacío.' });
else if (query.length > 1000) errores.push({ campo: 'query', problema: 'Máximo 1000 caracteres.' });

const sessionId = typeof body.session_id === 'string' ? body.session_id.trim() : '';
if (typeof body.session_id !== 'string') errores.push({ campo: 'session_id', problema: 'Es obligatorio y debe ser texto.' });
else if (!/^[A-Za-z0-9_-]{3,100}$/.test(sessionId)) errores.push({ campo: 'session_id', problema: 'Entre 3 y 100 caracteres: letras, números, guion o guion bajo.' });

const permitidos = ['query', 'session_id'];
const extra = Object.keys(body).filter((k) => !permitidos.includes(k));
if (extra.length) errores.push({ campo: extra.join(', '), problema: 'Campos no admitidos por el contrato.' });

return [{ json: { valido: errores.length === 0, errores, query, session_id: sessionId || null } }];

// Limpieza y normalización de correos (unidad CODE)
// Saca el HTML, corta el historial del hilo y las firmas, y recorta el texto.
const MAX_CHARS = 1200;

function htmlATexto(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

function normalizeContent(texto) {
  let limpio = String(texto || '').replace(/\r/g, '');
  const cortes = [
    /^\s*El .{0,200}escribi[oó]:\s*$/im,
    /^\s*On .{0,200}wrote:\s*$/im,
    /^-{2,}\s*(Original Message|Mensaje original)\s*-{2,}/im,
    /^\s*De:\s.*$/im,
    /^\s*From:\s.*$/im,
    /^--\s*$/m,
    /^Enviado desde mi /im,
    /^Sent from my /im
  ];
  for (const patron of cortes) {
    const m = limpio.match(patron);
    if (m && m.index > 0) limpio = limpio.slice(0, m.index);
  }
  limpio = limpio
    .split('\n')
    .filter((linea) => !linea.trim().startsWith('>'))
    .join('\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return limpio.length > MAX_CHARS ? limpio.slice(0, MAX_CHARS) + '…' : limpio;
}

const correos = $input.all()
  .filter((item) => item.json && item.json.id)
  .map((item) => {
    const c = item.json;
    const cuerpo = c.text ? c.text : htmlATexto(c.html);
    return {
      id: c.id,
      threadId: c.threadId,
      de: (c.from && c.from.text) || '',
      asunto: c.subject || '(sin asunto)',
      fecha: c.date || '',
      cuerpo: normalizeContent(cuerpo)
    };
  });

return [{ json: { total: correos.length, correos } }];

// Normaliza la lista de eventos de Google Calendar (ya en hora de Buenos Aires)
const eventos = $input.all()
  .filter((item) => item.json && item.json.id)
  .map((item) => {
    const e = item.json;
    return {
      id: e.id,
      titulo: e.summary || '(sin título)',
      inicio: (e.start && (e.start.dateTime || e.start.date)) || null,
      fin: (e.end && (e.end.dateTime || e.end.date)) || null,
      todo_el_dia: Boolean(e.start && e.start.date && !e.start.dateTime),
      link: e.htmlLink || null
    };
  });
return [{ json: { total: eventos.length, hay_conflicto: eventos.length > 0, eventos } }];

// Clasifica errores de las APIs de Google (Gmail y Calendar) con la misma lógica.
// - Transitorios (429, 5xx, timeouts, red): se reintentan con backoff exponencial + jitter.
// - Permanentes (400, 401, 403, 404): no se reintentan.
// - Escrituras (crear_evento, enviar_correo) NO se reintentan solas aunque el error sea
//   transitorio: la operación podría haberse completado y se duplicaría (idempotencia).
const MAX_INTENTOS = 3;
const ESCRITURAS = ['crear_evento', 'enviar_correo'];
const req = $('Preparar intento').last().json;
const entrada = $input.first().json || {};
const err = entrada.error || entrada;
const mensaje = (typeof err === 'string' ? err : String(err.message || err.description || JSON.stringify(err))).slice(0, 300);

let status = Number(err.httpCode || err.status || err.statusCode || 0);
if (!status) {
  const m = mensaje.match(/\b([45]\d\d)\b/);
  if (m) status = Number(m[1]);
}
if (!status) {
  const porTexto = [
    [/bad request|invalid/i, 400],
    [/unauthori[sz]ed|invalid credentials|token/i, 401],
    [/forbidden|insufficient permission/i, 403],
    [/not found/i, 404],
    [/too many requests|rate limit|quota/i, 429],
    [/internal server error/i, 500],
    [/bad gateway/i, 502],
    [/service unavailable|unavailable/i, 503],
    [/gateway timeout/i, 504]
  ];
  for (const [patron, codigo] of porTexto) {
    if (patron.test(mensaje)) { status = codigo; break; }
  }
}

const porRed = /timeout|timed out|ETIMEDOUT|ECONNRESET|ECONNREFUSED|ENOTFOUND|socket hang up|network/i.test(mensaje);
const transitorio = [429, 500, 502, 503, 504].includes(status) || porRed;
const esEscritura = ESCRITURAS.includes(req.accion);
const intento = Number(req.intento || 0);
const reintentar = transitorio && !esEscritura && intento + 1 < MAX_INTENTOS;
const espera = Math.pow(2, intento) + Math.round((0.1 + Math.random() * 0.4) * 100) / 100;

return [{
  json: {
    ...req,
    intento,
    reintentar,
    espera_seg: espera,
    http_status: status || null,
    tipo_error: transitorio ? 'transitorio' : 'permanente',
    escritura_sin_confirmar: transitorio && esEscritura,
    mensaje
  }
}];
